#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s! %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s-> opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: the steps only Colin and Riley can do for a Zero home.
#
#   tools/zero-home-wizard.sh riley     Google sign-in setup (once), Riley's tailnet invite, her phone,
#                                       her backup password, her first mailbox
#   tools/zero-home-wizard.sh test      only the Google sign-in setup, when it was never done
#
# The admin steps (users, /srv/zero, sudoers, AppArmor, Tailscale serve, the push key) are run by the lead
# with alien/bin/zero-home-sudo-prep before this wizard; see docs/qa/2026-10-09-zfa-wp3.md for the order.
# This wizard runs on Colin's Mac and reaches alien over ssh. It never asks for or stores a client secret.
# ──────────────────────────────────────────────────────────────────────────

HOME_ID="${1:-riley}"
ALIEN="${ZERO_ALIEN:-alien}"
REPO="$(cd "$(dirname "$0")/.." && pwd)"
mkdir -p "$HOME/.config/zero"
ENV_FILE="$HOME/.config/zero/wizard.env"

case "$HOME_ID" in
  riley) PERSON="Riley"; GMAIL="riley@example.com" ;;
  test)  PERSON="the test home"; GMAIL="" ;;
  *) echo "Usage: tools/zero-home-wizard.sh riley|test"; exit 2 ;;
esac

BUNDLE_ID=$(awk '/PRODUCT_BUNDLE_IDENTIFIER:/ {print $2; exit}' "$REPO/ios/project.yml")
CLIENT_ID_RE='^[0-9]{6,20}-[a-z0-9]{10,64}\.apps\.googleusercontent\.com$'
HAVE_CLIENT_ID=$(_existing ZERO_GOOGLE_CLIENT_ID || true)
ZERO_CLIENT_ID_DEFAULT="000000000000-yourgoogleclientid.apps.googleusercontent.com"
if [[ -z "$HAVE_CLIENT_ID" ]] && ! grep -qE '^ZERO_GOOGLE_CLIENT_ID=$' "$ENV_FILE" 2>/dev/null; then
  HAVE_CLIENT_ID="$ZERO_CLIENT_ID_DEFAULT"
fi

on_alien() { ssh -o BatchMode=yes "$ALIEN" "$@"; }

if [[ "$HOME_ID" == "test" && -n "$HAVE_CLIENT_ID" ]]; then
  printf '\n  The Google sign-in setup is already done (Zero'"'"'s client, project zero-signin).\n'
  printf '  The test home needs nothing else from Colin. The lead runs the rest.\n\n'
  exit 0
fi
GOOGLE_STAGES=5
[[ -n "$HAVE_CLIENT_ID" ]] && GOOGLE_STAGES=1
PERSON_STAGES=5
[[ "$HOME_ID" == "test" ]] && PERSON_STAGES=0
TOTAL_STAGES=$((1 + GOOGLE_STAGES + PERSON_STAGES))

banner "Zero: what only Colin and $PERSON can do"

stage "Check that alien is ready"
say "The lead should already have made the $HOME_ID home on alien. This checks that before anything else."
if on_alien "test -f /srv/zero/homes.json && python3 -c \"import json,sys; sys.exit(0 if '$HOME_ID' in json.load(open('/srv/zero/homes.json'))['homes'] else 1)\""; then
  printf '  %s✓%s alien has a home called %s.\n' "$GREEN" "$RESET" "$HOME_ID"
else
  warn "alien has no home called $HOME_ID yet. Ask the lead to finish the admin steps, then run this again."
  exit 1
fi
note "Nothing on alien changes in this stage."
pause "Press Enter to continue."

if [[ -n "$HAVE_CLIENT_ID" ]]; then
  stage "Google sign-in is already set up"
  say "The Google Client ID from an earlier run is saved, so the Google Cloud steps are skipped."
  if [[ -n "$GMAIL" ]]; then
    say "Make sure $GMAIL is on the test user list:"
    open_url "https://console.cloud.google.com/auth/audience"
    step "Under Test users, check that $GMAIL is listed. If it is not, click Add users, enter it and save."
  fi
  ZERO_GOOGLE_CLIENT_ID="$HAVE_CLIENT_ID"
  pause "Press Enter when the test user is on the list."
else
  stage "Make a Google Cloud project called Zero"
  say "Zero's Sign In with Google needs a Google Cloud project. You make it once, and every home uses it."
  open_url "https://console.cloud.google.com/projectcreate"
  step "Sign in with your own Google account if Google asks."
  step "In Project name, type Zero. Leave Location as it is."
  step "Click Create, then wait for the notification that the project is ready."
  step "Open the project picker at the top of the page and choose Zero, so the next pages use it."
  pause "Press Enter when the Zero project is selected."

  stage "Turn on the Gmail and Google Calendar APIs"
  say "The Zips read and draft mail through the Gmail API and read and add events through the Calendar API."
  open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
  step "Check that the project picker says Zero, then click Enable."
  pause "Press Enter when the Gmail API is enabled."
  open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
  step "Check that the project picker says Zero, then click Enable."
  pause "Press Enter when the Google Calendar API is enabled."

  stage "Set up the consent screen"
  say "This is the screen people see when they sign in with Google. It stays in Testing for now."
  open_url "https://console.cloud.google.com/auth/overview"
  step "Click Get started."
  step "App information: App name Zero. User support email: your address. Click Next."
  step "Audience: choose External. Click Next."
  step "Contact information: your address. Click Next, agree to the policy, and click Create."
  pause "Press Enter when the consent screen is created."
  open_url "https://console.cloud.google.com/auth/audience"
  step "Check that Publishing status says Testing. Leave it in Testing."
  if [[ -n "$GMAIL" ]]; then
    step "Under Test users, click Add users, enter $GMAIL and click Save."
  else
    step "Under Test users, add the Google account of each person who will sign in, then click Save."
  fi
  note "Testing allows up to 100 test users, and only test users can sign in."
  note "In Testing, Google ends a Gmail or Calendar sign-in after 7 days, so the person signs in again each week."
  note "Publishing the app for everyone needs Google's verification for the Gmail scopes. That is a later step."
  pause "Press Enter when the test user is added."

  stage "Choose what Zero may ask for"
  say "These are the permissions the sign-in asks for. Zero asks for nothing beyond them."
  open_url "https://console.cloud.google.com/auth/scopes"
  step "Click Add or remove scopes."
  step "In Manually add scopes, paste these five lines, then click Add to table:"
  note "    https://www.googleapis.com/auth/gmail.modify"
  note "    https://www.googleapis.com/auth/gmail.send"
  note "    https://www.googleapis.com/auth/calendar.events"
  note "    openid"
  note "    https://www.googleapis.com/auth/userinfo.email"
  step "Check that all five are ticked, click Update, then click Save at the bottom of the page."
  pause "Press Enter when the scopes are saved."

  stage "Make the iPhone sign-in client"
  say "The Zero app signs in with an iOS client. An iOS client has no secret, so nothing secret is copied here."
  open_url "https://console.cloud.google.com/auth/clients/create"
  step "Application type: iOS."
  step "Name: Zero iPhone."
  step "Bundle ID: $BUNDLE_ID"
  step "Leave the other fields empty and click Create."
  step "Copy the Client ID. It ends in .apps.googleusercontent.com."
  while true; do
    ask ZERO_GOOGLE_CLIENT_ID "Paste the Client ID:"
    if [[ "$ZERO_GOOGLE_CLIENT_ID" =~ $CLIENT_ID_RE ]]; then break; fi
    warn "That does not look like an iOS Client ID. It should look like 1234567890-abc123.apps.googleusercontent.com."
  done
  write_env ZERO_GOOGLE_CLIENT_ID "$ZERO_GOOGLE_CLIENT_ID"
fi

say ""
say "Next, the Client ID is written into every home's settings on alien (google.client_id)."
say "For each home other than yours this runs zero-home-render as that home's user, through the sudo rule"
say "the lead installed for /srv/zero/bin/zero-home-* scripts. Nothing else changes."
if confirm "Write the Client ID to every home on alien now?"; then
  for h in $(on_alien "python3 -c \"import json; print(' '.join(json.load(open('/srv/zero/homes.json'))['homes']))\""); do
    if on_alien "/srv/zero/bin/zero-home-render set $h google.client_id $ZERO_GOOGLE_CLIENT_ID" >/dev/null; then
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$h"
    else
      SKIPPED+=("google.client_id for the $h home (run: ssh $ALIEN /srv/zero/bin/zero-home-render set $h google.client_id <id>)")
      warn "Could not write it for $h."
    fi
  done
else
  SKIPPED+=("google.client_id on alien (run this wizard again, or zero-home-render set HOME google.client_id <id>)")
fi
pause "Press Enter to continue."

if [[ "$HOME_ID" == "test" ]]; then
  finish
  exit 0
fi

stage "Invite Riley to the tailnet"
say "Riley's phone reaches her home through Tailscale. She joins as her own Tailscale user, so her devices"
say "stay hers. Her home is published only on the tailnet, never on the internet."
open_url "https://login.tailscale.com/admin/users"
step "Click Invite users."
step "Enter $GMAIL and send the invite."
say "Then Riley, on her iPhone:"
step "Installs Tailscale from the App Store."
step "Opens the invite email and taps the link to accept it."
step "Signs in to Tailscale with Google, using $GMAIL, and allows the VPN configuration when iOS asks."
open_url "https://login.tailscale.com/admin/machines"
step "Check that Riley's iPhone appears on the Machines page."
note "Optional: an access rule can limit her devices to alien's port $(on_alien "python3 -c \"import json; print(json.load(open('/srv/zero/homes.json'))['homes']['riley']['ports']['serve_port'])\"" 2>/dev/null || echo 6444)."
note "The wizard does not change your tailnet rules; edit them on the Access controls page if you want that."
pause "Press Enter when her iPhone shows up on the Machines page."

stage "Install the Zero app on Riley's iPhone"
say "Until TestFlight exists, her phone gets the app from your developer account, like yours does."
step "Plug in her iPhone, unlock it, and tap Trust if it asks."
if ! grep -q -- "--device" "$REPO/ios/scripts/install-iphone.sh"; then
  warn "This copy of install-iphone.sh cannot pick a phone yet, and it would install on your iPhone."
  warn "Use a build where install-iphone.sh accepts --device, then run this wizard again."
  SKIPPED+=("the app on Riley's iPhone (install-iphone.sh needs --device)")
else
  xcrun devicectl list devices 2>/dev/null | sed 's/^/    /' || true
  ask RILEY_DEVICE "Type her iPhone's name or identifier from the list:"
  if [[ -n "${RILEY_DEVICE:-}" ]] && confirm "Build Zero and install it on \"$RILEY_DEVICE\" now?"; then
    if (cd "$REPO" && ios/scripts/install-iphone.sh --device "$RILEY_DEVICE"); then
      printf '  %s✓%s installed on %s\n' "$GREEN" "$RESET" "$RILEY_DEVICE"
    else
      SKIPPED+=("the app on Riley's iPhone (the install failed; see the output above)")
    fi
  else
    SKIPPED+=("the app on Riley's iPhone")
  fi
fi
step "On her iPhone: Settings, General, VPN and Device Management, then trust your developer profile if asked."
pause "Press Enter when Zero opens on her phone."

stage "Pair Riley's phone with her home"
say "This asks her home for a one-time pairing code, valid for an hour. It runs on alien as her home's user,"
say "through the sudo rule for /srv/zero/bin/zero-home-* scripts. Nothing else changes."
if confirm "Make a pairing code now?"; then
  PAIR_OUT=$(on_alien "/srv/zero/bin/zero-home-create riley --pair" 2>&1 || true)
  printf '%s\n' "$PAIR_OUT" | grep -E "Address|Code|Link" | sed 's/^/  /'
  LINK=$(printf '%s\n' "$PAIR_OUT" | awk '/Link:/ {print $2}')
  if [[ -n "$LINK" ]] && command -v qrencode >/dev/null 2>&1; then
    qrencode -t ansiutf8 "$LINK"
  elif [[ -n "$LINK" ]]; then
    note "For a QR code here, install qrencode (brew install qrencode). Riley can also type the address and code."
  else
    warn "No pairing code came back. Check her hub with: ssh $ALIEN systemctl --user status (as zero-riley)."
  fi
fi
say "Then Riley:"
step "Opens the Tailscale app and turns it on."
step "Opens Zero, taps I Have My Code, and scans the QR code, or types the address and the code."
pause "Press Enter when her phone shows her home."

stage "Keep Riley's backup password"
say "Her home's nightly backup is encrypted with a password that only you keep. It goes into your Mac's"
say "login keychain as \"Zero backup riley\", so the morning copy on this Mac can be checked. It is never"
say "shown on screen."
if confirm "Save her backup password in your keychain now?"; then
  if PW=$(on_alien "/srv/zero/bin/zero-home-create riley --show-backup-password" 2>/dev/null) && [[ -n "$PW" ]]; then
    security add-generic-password -U -s "Zero backup riley" -a zero-backup -w "$PW" >/dev/null
    unset PW
    printf '  %s✓%s saved as "Zero backup riley" in the login keychain\n' "$GREEN" "$RESET"
  else
    unset PW
    SKIPPED+=("Riley's backup password (ssh $ALIEN /srv/zero/bin/zero-home-create riley --show-backup-password)")
    warn "The password could not be read from her home."
  fi
else
  SKIPPED+=("Riley's backup password in your keychain")
fi
pause "Press Enter to continue."

stage "Riley connects her Gmail"
say "Her Zips read her mail and calendar after she signs in with Google in the app."
step "In Zero, Riley opens Email and Calendar and taps Sign In with Google."
step "She chooses $GMAIL."
step "Google says it has not verified the app. That is expected while it is in Testing: she taps Continue."
step "She allows Gmail and Calendar."
note "While the app is in Testing, Google ends this sign-in after 7 days and she signs in again."
pause "Press Enter when her mailbox shows as connected."

finish
